    for (let c = 0; c < cols; c++) {
      const v = row[c];
      if (v === 0) continue;
      for (let cc = 0; cc < cols; cc++) {
        if (cc !== c && row[cc] === v) return false;
      }
      for (let rr = 0; rr < rows; rr++) {
        const other = board[rr];
        if (rr !== r && other && c < other.length && other[c] === v) return false;
      }
      const br = Math.floor(r / 3) * 3;
      const bc = Math.floor(c / 3) * 3;
      const rEnd = Math.min(br + 3, rows);
      for (let rr = br; rr < rEnd; rr++) {
        const brow = board[rr];
        if (!brow) continue;
        const cEnd = Math.min(bc + 3, brow.length);
