function solve(board) {
  const rows = board.length;
  let cols = 0;
  for (let r = 0; r < rows; r++) {
    const row = board[r];
    if (row && row.length > cols) cols = row.length;
  }
  const boxCols = Math.ceil(cols / 3);
  const boxRows = Math.ceil(rows / 3);
  const inRow = [];
  const inCol = [];
  const inBox = [];
  for (let r = 0; r < rows; r++) inRow.push(new Set());
  for (let c = 0; c < cols; c++) inCol.push(new Set());
  for (let b = 0; b < boxRows * boxCols; b++) inBox.push(new Set());
  for (let r = 0; r < rows; r++) {
    const row = board[r];
    if (!row) continue;
    for (let c = 0; c < row.length; c++) {
      const v = row[c];
      if (v === 0) continue;
      const b = Math.floor(r / 3) * boxCols + Math.floor(c / 3);
      if (inRow[r].has(v) || inCol[c].has(v) || inBox[b].has(v)) return false;
      inRow[r].add(v);
      inCol[c].add(v);
      inBox[b].add(v);
    }
  }
  return true;
}
